/* pages.js — the list of html pages the gates walk, in one place.
   it used to be copied into check-security, check-i18n, verify-shell and
   apply-security; four copies meant a new page could ship and quietly stay
   outside the security and language checks. share the list, miss it once.   */

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

// hand-written pages, in the order a visitor meets them
const SHARED = ['index.html', '404.html', 'privacy.html', 'terms.html', 'stats.html', 'admin.html'];

// the case pages are generated by build-cases.js from work/*.json
const CASES = fs.readdirSync(path.join(ROOT, 'work'))
  .filter((f) => f.endsWith('.html'))
  .map((f) => 'work/' + f);

module.exports = { ROOT, SHARED, CASES, PAGES: SHARED.concat(CASES) };
